import json
import os
import asyncio
from dataclasses import dataclass
from httpx import AsyncClient
# import boto3
import base64
# import urllib
# from dotenv import load_dotenv

# import logfire
from pydantic_ai import Agent, BinaryContent
from pydantic_ai.models.bedrock import BedrockConverseModel
from pydantic_ai.providers.bedrock import BedrockProvider
from pydantic import BaseModel

# logfire.configure()
# logfire.instrument_pydantic_ai()

@dataclass
class Deps:
    client: AsyncClient

class Food(BaseModel):
    foundationName: str
    fullFoodName: str

provider = BedrockProvider(region_name="us-east-1")
model = BedrockConverseModel("us.anthropic.claude-haiku-4-5-20251001-v1:0", provider=provider)

food_agent = Agent(model, output_type=[Food, str], instructions ="""Classify the image input as both a Foundation food item 
                                        according to USDA naming with no brand, just the general food it is. Additionally classify as full branded food item, the entire name of the food. Answer only with food name, nothing else.""")

# s3 = boto3.client('s3')

def lambda_handler(event, context):
    data = json.loads(event.get('body', '{}'))

    # file_name = data.get('fileName')
    content_type = data.get('contentType')
    image_base64 = data.get('base64Image')

    if not image_base64:
        return {
                'isBase64Encoded': False,
                'statusCode': 400,
                'headers': {
                    'Content-Type': "application/json",
                    "Access-Control-Allow-Origin": "*"
                },
                'body': json.dumps({'nutritionInfo': None, 'error': 'Missing image data'})
            }

    decoded_image = base64.b64decode(image_base64)

    result = asyncio.run(classify_and_lookup(decoded_image, content_type))

    print("Claude classified as", result['classification'])


    # bucket = event['Records'][0]['s3']['bucket']['name']
    # key = urllib.parse.unquote_plus(event['Records'][0]['s3']['object']['key'], encoding='utf-8')

    # parts = key.split('/')
    # upload_id = parts[2].split('.')[0]

    # result = asyncio.run(classify_and_lookup(bucket, key))

    return {
                'isBase64Encoded': False,
                'statusCode': 200,
                'headers': {
                    'Content-Type': "application/json",
                    "Access-Control-Allow-Origin": "*"
                },
                'body': json.dumps({'nutritionInfo': result["fdc_data"]})
            }

async def classify_and_lookup(decodedImage, contentType) -> dict:
    # response = s3.get_object(Bucket=bucket, Key=key)
    # image_bytes = response['Body'].read()
    result = await food_agent.run(['Classify the food',
                                    BinaryContent(data=decodedImage, media_type=contentType)])
    # classification = result.output.strip()
    classification = result.output.foundationName.strip()

    # USDA FDC search
    api_key = os.environ["FOOD_API"]
    async with AsyncClient() as client:
        # logfire.instrument_httpx(client, capture_all=True)
        fdc_response = await client.get(
            "https://api.nal.usda.gov/fdc/v1/foods/search",
            params={
                "query": classification,
                "dataType": "Foundation",
                "api_key": api_key,
            },
        )
        fdc_response.raise_for_status()
        fdc_data = fdc_response.json()

    return {"classification": classification, "fdc_data": fdc_data}

